export const meta = {
  name: 'history-census-families',
  description: 'The history read the trade pilot proved (+10 % cars, three re-statused waves, one mandatory car 0), run over the other simulation families ONE FAMILY AT A TIME in the architecture\'s boarding order (WF POP WY IN WC, then HB INT GR-CW LG only if every one of the first five yields a status change or a record≠code row) — two readers per family (the ledger · the older programme), an adjudicator who reads the volume whole, a skeptic, a fold; every reader WRITES ITS OWN FILE and hands the path. Paced serially because the 19:1x fan-out (15 readers at once) burned the session window in eight minutes',
  phases: [
    { title: 'Read', detail: 'per family, two readers in parallel — each writes history/<FAM>/<reader>.md' },
    { title: 'Adjudicate', detail: 'per family — every claim followed to the code at the consist; the volume read whole' },
    { title: 'Refute', detail: 'per family — the skeptic re-derives every verdict' },
    { title: 'Fold', detail: 'per family — HISTORY-<FAM>-2026-09-15.md' },
  ],
}
const L = '/private/tmp/claude-502/-Users-cstokes-Desktop-settlement-engine/f6ac0d98-bb14-48ae-88d1-c6887f1e2704/scratchpad/ledger-a803dee7a'
const S = '/private/tmp/claude-502/-Users-cstokes-Desktop-settlement-engine/4e3d2f70-f45f-4e14-b571-514c339cfa17/scratchpad/kit/laneCONSIST-932'
const KIT = '/private/tmp/claude-502/-Users-cstokes-Desktop-settlement-engine/4e3d2f70-f45f-4e14-b571-514c339cfa17/scratchpad/kit'
const PROG = '/private/tmp/claude-502/-Users-cstokes-Desktop-settlement-engine/f6ac0d98-bb14-48ae-88d1-c6887f1e2704/scratchpad/recon-32-34/PROGRAMME-32-34.md'
const RECHECK = '/private/tmp/claude-502/-Users-cstokes-Desktop-settlement-engine/f6ac0d98-bb14-48ae-88d1-c6887f1e2704/scratchpad/recon-32-34/RECHECK-32-34.md'
const PRICING = '/private/tmp/claude-502/-Users-cstokes-Desktop-settlement-engine/f6ac0d98-bb14-48ae-88d1-c6887f1e2704/scratchpad/recon-32-34/PRICING-32-33.md'
const OUT = '/private/tmp/claude-502/-Users-cstokes-Desktop-settlement-engine/f6ac0d98-bb14-48ae-88d1-c6887f1e2704/scratchpad/recon-32-34'
const TRADE = `${OUT}/HISTORY-TRADE-2026-09-15.md`
const H = `${OUT}/history`

const FAMILIES = [
  { code: 'WF', name: 'faith (47–74 C)', volumes: ['WF'], older: 'June Track B\'s "4th deity axis"; the deity doctrine (faith = culture, never theological; THE FOLLOWERS ACT, THE GOD DOES NOT — ADDENDUM 15); SP-B\'s DEVOTION_BANDS (beliefAxisSubjects.js); GR-2\'s faith_communion producer (PRICING already notes "build the read, not the seam"); the creed standing (cult/established/ascendant · patron · legitimacy · share band); the temple/institution lifecycle; the deity axes (alignment · law · derived temper · pantheon rank)', terms: 'faith, creed, deity, god, pantheon, temple, clergy, priest, devotion, tithe, heresy, schism, communion, patron, legitimacy, cult, ascendant, WF-, faithCommunion, DEVOTION_BANDS, beliefAxis, deityAxes' },
  { code: 'POP', name: 'populations (32–45 C)', volumes: ['POP'], older: 'July\'s demographics programme (demographicsMigration.js — MIGRATION_REFUSALS :107-109 and capacity-ranked placement :231-242 landed WITHOUT POP-1: ODQ §49\'s blocker is DEAD, a RECORD≠CODE the trade pilot found by accident); demographicsObservation.js (the realmPressure01 producer — test it for a frozen-ground-truth analogue: who writes what it reads?); demographicsPlans.js (the planning fence); the reception contract C-POPF-2 (ODQ §92.3); M11a pestilence (`82ad676b2`); the household/dwellings programme (DESIGN_DWELLINGS_PROGRAM); foodGenerator.js\'s foodRatio (generation-frozen)', terms: 'population, migration, migrant, refugee, reception, household, dwelling, birth, death, plague, pestilence, famine, hunger, realmPressure, demographic, census, POP-, MIGRATION_REFUSALS, demographicsMigration, demographicsObservation, foodRatio' },
  { code: 'WY', name: 'wayfare (44–67 C)', volumes: ['WY'], older: 'M2 caravans (`67a946616`) and M8 sea lanes (`618dba590`) ARE mover bodies; M1 embattlement routing (`4f76f1ee2`); roadsKernel.js (838/838, at its ceiling); the J1–J4 route network (`ed5ac49dd`, 17 modules, DARK behind routeLifecycleEnabled: false; zero WHAT_PHRASES, zero heraldRouting rows); teleportEdges.js; navalLayer.js; the WY-3/TR-4 inversion ruling (PRICING §A.4: TR-4 before WY-3)', terms: 'road, route, path, caravan, wayfare, travel, journey, ship, sea lane, port, harbour, bridge, ford, pass, toll, embattlement, distance, WY-, roadsKernel, routeNetwork, routeLifecycle, seaLanes, supplyShipments, distanceRead' },
  { code: 'IN', name: 'information (27–38 C)', volumes: ['IN'], older: 'brokerageServices.js (INFO\'s news brokerage — its houseId at :457 is an institution, NOT a merchant house); M6c/M8 rumour carriers; M11a\'s plague carrier; the Herald (heraldIndex.js, heraldRouting, WHAT_PHRASES); news reliability stamps; the espionage layer\'s intelligence products; the news address law (address chain + typed action + names + reason)', terms: 'news, rumour, rumor, herald, brokerage, courier, messenger, intelligence, report, reliability, gossip, proclamation, dispatch, letter, IN-, brokerageServices, heraldRouting, heraldIndex, newsReliability, WHAT_PHRASES' },
  { code: 'WC', name: 'war circulation (#32\'s largest family, 97–148 C; the 09-15 measurement called #34 three-quarters built)', volumes: ['WC'], older: 'W-COIN · W-SEAT · W-OPS · W-DESK landed under W-names 08-30/09 ("W-DESK landed unrecorded" is a known RECORD≠CODE); June Track B\'s war deepening (`77bd27ae1`/`e1c7244e9`); warCoalitionSettlement.js, demographicsWar.js, warReasons.js, warDeployment.js (the §733.2 razing-spoils RECORD≠CODE: :788 reads economicState.wealthIndex which has zero writers); treasury.js (§793/§842; the §763.2 lit-promise RECORD≠CODE); the espionage layer\'s war reads', terms: 'war, campaign, siege, levy, muster, coalition, spoils, razing, treasury, coffers, tax, upkeep, garrison, deploy, capitulation, tribute, WC-, W-COIN, W-SEAT, W-OPS, W-DESK, W-ARMS, warDeployment, demographicsWar, warReasons, warCoalition' },
  { code: 'HB', name: 'habit (35–61 C)', volumes: ['HB'], older: 'dailyLifeLogic, the culture profiles, the two persisted habit fields (exist dark), Q1\'s three stamped fields, the calendar/season machinery, the festival/ritual copy in the institution catalog', terms: 'habit, daily life, custom, ritual, festival, calendar, season, routine, leisure, feast, market day, HB-, dailyLife, cultureProfile, habitField' },
  { code: 'INT', name: 'interior (34–47 C)', volumes: ['INT'], older: 'the T8 taxonomy train (`64c344615`: 27 craft institutions re-filed out of government, ~800 given a faction nameplate — a FALSE-POSITIVE class: generation-time power structure, no simulation body), the institution lifecycle, stressorsCore.js (the EAGER row INT-3a measures against a built dist), institutionalCatalog.js priorityCategory', terms: 'institution, guild, council, court, charter, lifecycle, founding, dissolution, stressor, interior, INT-, institutionalCatalog, priorityCategory, stressorsCore, institutionLifecycle' },
  { code: 'GR-CW', name: 'grammar + couplings (35–55 C)', volumes: ['GR', 'CW'], older: 'GR is itself the older programme for TR (GR-2 `a18fdcfae` the peacetime pact lifecycle; GR-3a `0be4800db` the trade-rights rows); CW is a terminus (SC-6 the causedBy walker → CW-1..CW-3); pulseKernel.js 1581/1581 mount-blocks GR-4/GR-6 (an extraction car first); peaceTerms.js 797/800', terms: 'grammar, treaty, term, clause, pact, executor, seam, coupling, causedBy, GR-, CW-, SC-6, pactFormation, peaceTermsCatalog, treatyOrientation, peaceTerms, couplingRegistry' },
  { code: 'LG', name: '#33 logistics — the first train LG-0/LG-1 (11–17 C)', volumes: [], older: 'the circle network, airship cargo, ship+circle news and a custody ledger ALREADY landed under other lineages (no LG wave, no LG flag — RECHECK §1.2); teleportEdges.js; foodImportRates.js:17-22 (airship rates); navalLayer.js ("DERIVED, NEVER PERSISTED"); ODQ §46 / §46a / §46c / §49 / §92.1 / §92.3 / §125 / §125a (all DESIGNED-ONLY per the trade pilot rows 34–43); the §49 dead POP-1 blocker; the Q10 band-walker prefix (lane D, landed); DESIGN_FP_ARCH_LG.md has NEVER existed on a build branch (lane D) — #33 cannot author a band into an absent volume', terms: 'logistics, airship, teleport, circle, vessel, fleet, cargo, custody, convoy, escort, blockade, LG-, teleportEdges, navalLayer, foodImportRates, circleNetwork' },
]
const BATCH1 = FAMILIES.slice(0, 5)
const BATCH2 = FAMILIES.slice(5)

const volumesOf = (f) => f.volumes.length ? f.volumes.map(v => `${L}/docs/DESIGN_FP_ARCH_${v}.md`).join(' and ') : `NO VOLUME (#33 has none on any branch — its record is the ODQ §46/§46a/§46c/§49/§92/§125/§125a entries, RECHECK §1.2 and PRICING §B "LG — #33 first train")`

const commonFor = (f) => `READ-ONLY: never run vitest or npm, never mutate git; write ONLY under ${H}/${f.code}/ (create it with mkdir -p) and, if you are the folder, ${OUT}. THE OWNER'S QUESTION: "look at all of the past logs of what was designed to see if they built any of this in more depth" — TRADE was the pilot and its fold is ${TRADE}: read its §A.1, §A.3, §A.4, the grep-trap paragraph after §B, and §C WHOLE before you start — it is the standard (every figure CONFIRMED by an executed receipt with path:line, or PLAUSIBLE), the shape, and the trap list; do NOT redo trade. THIS FAMILY: ${f.code} — ${f.name}. Its waves are listed in ${volumesOf(f)}. The two code passes' rows for it: ${PROG} §B (per-wave status with evidence) and ${RECHECK} §1 (the corrected rows) with the grep traps in §5; ${PRICING} §B prices its waves and §C boards its lanes. THE HISTORY SOURCES: the product lineage \`claude/composite-r4\` in ${S} — \`git -C ${S} log --all --format='%h %ad %s' --date=short -i --grep=<term>\` over subjects AND bodies, and \`-S<identifier>\` for code terms; the commit BODIES name the waves and cars they land, quote gates and cite the ledger §; ~540 cars since ca651d54b and thousands before on \`claude/composite-r3\`, \`claude/the-composite\`, \`master\`; the LEDGER ${L}/docs/OWNER_DECISION_QUEUE.md (3.4 MB, ~32,700 lines — grep -n, then sed -n the section; its §-entries record landings with shas and RULINGS that stop, freeze, re-charter or block waves — the trade pilot's decisive find was such a ruling, ODQ §96.2); ${L}/docs/START_HERE.md, A_PLUS_ROADMAP.md, SOL_QUEUE.md, FABLE_VALIDATION_QUEUE.md (where the pilot found the ONLY record of two landings), GOLDEN_SHIFT_LEDGER.md, and the design docs under ${L}/docs (ls docs/DESIGN_*). THE DIARY ${KIT}/RESUME-NOTE.md is NOT a source (it begins 2026-09-08; every #32 landing predates it). THE OLDER PROGRAMMES THAT MAY HAVE BUILT THIS FAMILY'S WAVES UNDER ANOTHER NAME: ${f.older}. SEARCH TERMS TO START FROM (derive more from the volume's wave list and every identifier its §1 substrate rows name): ${f.terms}. A claim counts as BUILT only when the code at ${S} does the wave's DESCRIBED behaviour today (path:line); a leaf that exists but no preset lights is LANDED-DARK; a leaf nothing reaches is LANDED-INERT; substrate the wave was chartered to CONSUME is not the wave; the ledger saying a thing the consist contradicts is RECORD-NE-CODE (record it — the pilot found three). Every grep trap in RECHECK §5 and in the trade fold applies (INSTR-1 matches TR-1; check every wave-id substring hit's context). YOUR STRUCTURED RETURN HOLDS AT MOST 25 CLAIMS — the FULL claim table goes in YOUR FILE, and you hand its path in \`file\`: the pilot's payloads were truncated at ~30 KB and its late waves rested on summaries; do not repeat that.`

// THE CHECKPOINT RULE (the owner, 23:4x). Gated: WF and POP are done or in flight and keep their cached prompts; WY onward checkpoint.
const DONE_FAMILIES = ['WF', 'POP']
const CHECKPOINT = (f, label) => DONE_FAMILIES.includes(f.code) ? '' : ` CHECKPOINT RULE: (1) at your FIRST step create ${H}/${f.code}/progress-${label}.txt (mkdir -p ${H}/${f.code}) and APPEND one line after every meaningful step (a section grepped and its hits; a claim confirmed at path:line; a table section written) in the form 'HH:MM · <step> · <what is now known> · next: <the next step>'; (2) write your output file EARLY with its skeleton and RE-WRITE it after every section you finish (the Write tool overwrites; a half-written table with confirmed rows is worth more than a perfect one that never lands); (3) if ${H}/${f.code}/progress-${label}.txt ALREADY EXISTS when you start, you are RESUMING after a death or a spent window: read it and your partial output FIRST, keep every confirmed row, and continue from its last 'next:' line, never from scratch. Return only when your file is complete; your last progress line says 'DONE'.`
const SCHEMA = { type: 'object', properties: { reader: { type: 'string' }, file: { type: 'string', description: 'the file you wrote with the FULL claim table' }, claims: { type: 'array', maxItems: 25, items: { type: 'object', properties: { what: { type: 'string' }, source: { type: 'string', description: 'sha + date + subject, or the ledger §/line' }, wave: { type: 'string', description: 'which wave of this family, or the older-programme name it belongs to, or NONE' }, status: { type: 'string', enum: ['LANDED-IN-CODE', 'LANDED-DARK', 'LANDED-INERT', 'LANDED-THEN-REVERTED', 'DESIGNED-ONLY', 'RECORD-NE-CODE', 'UNKNOWN'] }, codeEvidence: { type: 'string' }, label: { type: 'string', enum: ['CONFIRMED', 'PLAUSIBLE'] } }, required: ['what', 'source', 'wave', 'status', 'codeEvidence', 'label'] } }, summary: { type: 'string' } }, required: ['reader', 'file', 'claims', 'summary'] }
const FOLD_SCHEMA = { type: 'object', properties: { file: { type: 'string' }, summary: { type: 'string' }, statusChanges: { type: 'integer', description: 'waves whose status differs from PRICING §B / RECHECK §1' }, recordNeCodeRows: { type: 'integer' }, mandatoryCar0: { type: 'integer' }, carDeltaLow: { type: 'integer' }, carDeltaHigh: { type: 'integer' }, wavesBuilt: { type: 'integer' }, wavesPart: { type: 'integer' }, wavesUnbuilt: { type: 'integer' } }, required: ['file', 'summary', 'statusChanges', 'recordNeCodeRows', 'mandatoryCar0', 'carDeltaLow', 'carDeltaHigh', 'wavesBuilt', 'wavesPart', 'wavesUnbuilt'] }

const readStage = (f) => parallel([
  () => agent(`${commonFor(f)}\n\nYOU ARE THE LEDGER READER for ${f.code}.${CHECKPOINT(f, 'ledger')} Over ${L}/docs/OWNER_DECISION_QUEUE.md and the queue docs, find EVERY entry that records a landing, a design decision, a RULING (a stop, a freeze, a re-charter, a blocker — and whether that blocker is still alive in the code), or a deferral for this family (grep -n -i over the terms and the wave ids '${f.code.split('-')[0]}-[0-9]'; beware the INSTR-1≠TR-1 class of substring trap — read every wave-id hit's context). For each: what was decided or landed, the § and line, the sha it names, the wave, and whether the ledger later records it reverted, banked, superseded — or the consist contradicts it (RECORD-NE-CODE: open the code at ${S} and quote path:line). There is no separate git-log reader in this run: for every sha the ledger names, verify it with \`git -C ${S} log -1 --format='%h %ad %s' --date=short <sha>\` and, for the family's wave ids and the volume's leaf names, run \`git -C ${S} log --all --format='%h %ad %s' --date=short -i --grep=<term>\` so landings the ledger never recorded (the pilot found two only in FABLE_VALIDATION_QUEUE.md) still enter your table. Write the FULL table in ledger order to ${H}/${f.code}/ledger.md with the Write tool (mkdir -p first), then return the structured object (≤ 25 claims, the file path, a summary).`, { label: `read:${f.code}:ledger`, phase: 'Read', schema: SCHEMA, model: 'opus' }),
  () => agent(`${commonFor(f)}\n\nYOU ARE THE OLDER-PROGRAMME READER for ${f.code}.${CHECKPOINT(f, 'older')} The older programmes named above predate the family's volume: read their design docs under ${L}/docs (ls docs/DESIGN_* and grep for the terms), their ledger entries, and THEIR CODE at ${S}. For each wave of ${f.code} (read the wave's DESCRIBED behaviour in the volume's §4, or the ODQ entries for #33), decide whether an older programme already implements that behaviour under another name — path:line — a fragment of it, or only its substrate; and ask the pilot's two questions of every mechanism you find: WHAT DOES IT READ (is its ground truth live, or generation-frozen? the pilot found foodRatio written only by the generator, which froze a whole belief axis), and IS IT REACHABLE (a caller on a production path, a dark leaf, or an UNFLAGGED LIVE PRODUCER the wave must reconcile with — the pilot found famine profiteering shipping ungated as sentiment). Write the FULL table to ${H}/${f.code}/older.md with the Write tool (mkdir -p first), then return the structured object (≤ 25 claims, the file path, a summary).`, { label: `read:${f.code}:older`, phase: 'Read', schema: SCHEMA, model: 'opus' }),
]).then(rs => ({ readers: rs.filter(Boolean) }))

const adjudicateStage = (prev, f) => {
  if (!prev || !prev.readers.length) throw new Error(`${f.code}: no reader returned`)
  const files = prev.readers.map(r => r.file).join(', ')
  const sums = prev.readers.map(r => `${r.reader}: ${r.summary}`).join('\n\n').slice(0, 24000)
  return agent(`${commonFor(f)}\n\nYOU ARE THE ADJUDICATOR for ${f.code}.${CHECKPOINT(f, 'adjudicator')} Read the family's volume WHOLE (${volumesOf(f)}) — its §1 substrate rows are the prior for how much older machinery exists; its wave list and each wave's description; its progress/landing block. Then read the readers' files WHOLE: ${files}. Their summaries:\n${sums}\n\nFor EVERY claim marked LANDED-IN-CODE, LANDED-DARK, LANDED-INERT, RECORD-NE-CODE or UNKNOWN, open the cited code at ${S} and decide by reading: the wave's described behaviour, a fragment of it, or substrate only; reachable on a production path or not. Produce the WAVE-BY-WAVE verdict for every wave of ${f.code}: BUILT / PART-BUILT (which parts, path:line) / UNBUILT, and for each PART-BUILT what the remaining cars must add so PRICING §B's row can be re-cut. Name every MANDATORY CAR 0 (a frozen or destructive charter, a dead blocker, a live producer to reconcile), every JOIN CAR (a frozen ground truth), every RECORD-NE-CODE row, and every grep trap you confirmed. Write ${H}/${f.code}/adjudicator.md with the Write tool (the full verdict), then return the structured object (one claim per wave, ≤ 25, the file path, a summary that states the count built/part/unbuilt).`, { label: `adjudicate:${f.code}`, phase: 'Adjudicate', schema: SCHEMA, model: 'opus', effort: 'high' }).then(a => ({ ...prev, adjudicator: a }))
}

const refuteStage = (prev, f) => {
  if (!prev || !prev.adjudicator) throw new Error(`${f.code}: no adjudicator verdict`)
  return agent(`${commonFor(f)}\n\nYOU ARE THE SKEPTIC for ${f.code}.${CHECKPOINT(f, 'skeptic')} The adjudicator's verdict is at ${prev.adjudicator.file} (read it whole; its summary: ${String(prev.adjudicator.summary).slice(0, 6000)}); the readers' files are ${prev.readers.map(r => r.file).join(', ')}. Re-derive EVERY wave's verdict yourself from the code at ${S} and the volume (${volumesOf(f)}): attack each BUILT/PART-BUILT for reachability (a production path, or a dark leaf? the wave's behaviour, or its substrate? live ground truth, or generation-frozen?) and search each UNBUILT two further ways — by the wave's FICTION, not its identifiers (the pilot's skeptic found famine profiteering shipping ungated and a frozen ground truth that way). Verify every sha the adjudicator cites by \`git log -1\`. Default to the more conservative status when uncertain; label each verdict CONFIRMED (an executed receipt quoted) or PLAUSIBLE. Write ${H}/${f.code}/skeptic.md with the Write tool, then return the corrected wave-by-wave verdict (≤ 25 claims, the file path, a summary naming every correction you made to the adjudicator).`, { label: `refute:${f.code}`, phase: 'Refute', schema: SCHEMA, model: 'opus', effort: 'high' }).then(sk => ({ ...prev, skeptic: sk }))
}

const foldStage = (prev, f) => {
  if (!prev || !prev.skeptic) throw new Error(`${f.code}: no skeptic verdict`)
  const files = [...prev.readers.map(r => r.file), prev.adjudicator.file, prev.skeptic.file].join(', ')
  return agent(`You are the chair's folder for family ${f.code} (${f.name}). READ-ONLY except ${OUT}.${CHECKPOINT(f, 'fold')}${f.code === 'POP' ? ` IF ${OUT}/HISTORY-${f.code}-2026-09-15.md ALREADY EXISTS (it does: the previous folder wrote it and was killed before returning), READ IT WHOLE, verify its §A.4 counts against its own tables, and return the structured object FROM IT without rewriting; only if it is absent or truncated do the work below.` : ''} Read the trade pilot's fold ${TRADE} first for the SHAPE, then read these five files WHOLE: ${files}. The adjudicator's summary: ${String(prev.adjudicator.summary).slice(0, 5000)}. The skeptic's summary: ${String(prev.skeptic.summary).slice(0, 5000)}. Write ${OUT}/HISTORY-${f.code}-2026-09-15.md with the Write tool in EXACTLY the trade fold's shape: (A) THE ANSWER FIRST — A.1 one paragraph for the owner in plain words (did the history show more of this family built than the two code passes found, and under whose name); A.2 wave by wave — the recon row from PRICING §B / RECHECK §1, what the history shows, the skeptic's verdict, the label; A.3 what the older programmes already do that the waves describe (and why each is not the wave); A.4 the corrected car estimate against PRICING §B with the reason per wave, lighting NOT priced per wave (it lives in the single declared window, PRICING §D); (B) the full claim table (sha/§, date, subject, wave, status, evidence, label) and the grep traps banked; (C) the method's yield for this family — the findings name-search could not produce, and what the next family's readers should do differently. Every figure CONFIRMED or PLAUSIBLE; every path:line at ${S}. Return the structured object: the file, a 10-line summary, and the counts (status changes vs PRICING §B / RECHECK §1; RECORD-NE-CODE rows; mandatory car 0s; the car delta low/high; built/part/unbuilt).`, { label: `fold:${f.code}`, phase: 'Fold', schema: FOLD_SCHEMA, effort: 'high' })
}

const runBatch = async (fams) => {
  const out = []
  for (const f of fams) {
    log(`History census: ${f.code} (one family at a time — paced to the session window)`)
    let r = null
    try {
      const a = await readStage(f)
      const b = await adjudicateStage(a, f)
      const c = await refuteStage(b, f)
      r = await foldStage(c, f)
    } catch (e) { log(`${f.code}: ${e && e.message ? e.message : e}`) }
    out.push(r)
  }
  return out
}

log(`Batch 1: ${BATCH1.map(f => f.code).join(' → ')} (the architecture's boarding order, so each fold lands before its family is architected)`)
const folds1 = await runBatch(BATCH1)
const done1 = folds1.map((r, i) => ({ code: BATCH1[i].code, r })).filter(x => x.r)
const missing1 = BATCH1.filter((f, i) => !folds1[i]).map(f => f.code)
if (missing1.length) log(`Batch 1 families WITHOUT a fold (a stage threw or an agent died): ${missing1.join(', ')}`)
for (const d of done1) log(`${d.code}: ${d.r.wavesBuilt}/${d.r.wavesPart}/${d.r.wavesUnbuilt} built/part/unbuilt · ${d.r.statusChanges} status change(s) · ${d.r.recordNeCodeRows} record≠code · car 0s ${d.r.mandatoryCar0} · cars ${d.r.carDeltaLow >= 0 ? '+' : ''}${d.r.carDeltaLow}…${d.r.carDeltaHigh}`)

const go = done1.length === BATCH1.length && done1.every(d => d.r.statusChanges >= 1 || d.r.recordNeCodeRows >= 1)
let folds2 = null
if (go) {
  log(`Every batch-1 family yielded — batch 2: ${BATCH2.map(f => f.code).join(' → ')}`)
  folds2 = await runBatch(BATCH2)
  const missing2 = BATCH2.filter((f, i) => !folds2[i]).map(f => f.code)
  if (missing2.length) log(`Batch 2 families WITHOUT a fold: ${missing2.join(', ')}`)
  folds2.forEach((r, i) => { if (r) log(`${BATCH2[i].code}: ${r.wavesBuilt}/${r.wavesPart}/${r.wavesUnbuilt} · ${r.statusChanges} status change(s) · ${r.recordNeCodeRows} record≠code · car 0s ${r.mandatoryCar0} · cars ${r.carDeltaLow}…${r.carDeltaHigh}`) })
} else {
  log(`Batch 2 NOT run by the pilot's rule (every first-five family must yield ≥ 1 status change or record≠code row; missing folds count as no yield): skipped ${BATCH2.map(f => f.code).join(', ')}`)
}
return {
  batch1: done1.map(d => ({ code: d.code, file: d.r.file, counts: [d.r.wavesBuilt, d.r.wavesPart, d.r.wavesUnbuilt], statusChanges: d.r.statusChanges, recordNeCode: d.r.recordNeCodeRows, car0: d.r.mandatoryCar0, cars: [d.r.carDeltaLow, d.r.carDeltaHigh], summary: d.r.summary })),
  batch1Missing: missing1,
  batch2: folds2 ? folds2.map((r, i) => r ? ({ code: BATCH2[i].code, file: r.file, counts: [r.wavesBuilt, r.wavesPart, r.wavesUnbuilt], statusChanges: r.statusChanges, recordNeCode: r.recordNeCodeRows, car0: r.mandatoryCar0, cars: [r.carDeltaLow, r.carDeltaHigh], summary: r.summary }) : ({ code: BATCH2[i].code, missing: true })) : 'skipped by the pilot rule',
}
